"""Bounded redacted GenAI content. No business values are modified.

Schemas are the complete official snapshot shipped as an application asset.
Known discriminators are validated separately because GenericPart is permissive.
"""
from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

from jsonschema import Draft202012Validator

MAX_MESSAGES = 16
MAX_PARTS = 64
MAX_BYTES = 8192
SCHEMAS = json.loads(Path(__file__).with_name("content_schemas.json").read_text())
PREFIX = "model/gen-ai/gen-ai-"
VALIDATORS = {name: Draft202012Validator(schema) for name, schema in SCHEMAS.items()}
PROTECTED = re.compile(
    r"(?:hidden|private|reasoning|chain.?of.?thought|password|secret|token|credential|"
    r"api.?key|authorization|email|(?:^|_)\w*id$)", re.I,
)
LABEL = re.compile(
    r"\b(?:hidden[-_ ]reasoning|private[-_ ]prompt|reasoning|chain[-_ ]of[-_ ]thought|"
    r"api[-_ ]key|access[-_ ]token|token|password|secret|authorization|email|"
    r"user[-_ ]id|account[-_ ]id|order[-_ ]id)\s*[:=]\s*"
    r"(?:\"[^\"]*\"|'[^']*'|[^;\n,}]+)", re.I,
)
EMAIL = re.compile(r"[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+\.[A-Z]{2,}", re.I)
PRIVATE = re.compile(r"\bprivate[-_]prompt(?:[-_][\w-]+)?\b", re.I)


def encode(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)


def text(value: str, limit: int) -> str:
    return value.encode("utf-8")[:limit].decode("utf-8", errors="ignore")


def validate_messages(messages: Any, output: bool = False) -> None:
    name = PREFIX + ("output" if output else "input") + "-messages.json"
    schema = SCHEMAS[name]
    VALIDATORS[name].validate(messages)
    known = {
        definition["properties"]["type"]["const"]: definition_name
        for definition_name, definition in schema["$defs"].items()
        if "const" in definition.get("properties", {}).get("type", {})
    }
    for message in messages:
        for part in message["parts"]:
            if part["type"] in known:
                concrete = {"$defs": schema["$defs"], "$ref": "#/$defs/" + known[part["type"]]}
                Draft202012Validator(concrete).validate(part)


def sanitize(value: Any, *, leaf_bytes: int = 2048, depth: int = 0) -> Any:
    if depth > 16:
        return "[truncated]"
    if isinstance(value, str):
        # Decode once, then recurse into containers or sanitize the decoded scalar.
        try:
            decoded = json.loads(value)
        except (ValueError, RecursionError):
            decoded = value
        if not isinstance(decoded, str):
            return sanitize(decoded, leaf_bytes=leaf_bytes, depth=depth + 1)
        return text(PRIVATE.sub("[redacted]", EMAIL.sub("[redacted]", LABEL.sub("[redacted]", decoded))), leaf_bytes)
    if isinstance(value, dict):
        if PROTECTED.search(str(value.get("type", ""))):
            return {"type": "text", "content": "[redacted]"}
        if "type" in value:
            # Reject a malformed known part before any TextPart representation.
            validate_messages([{"role": "user", "parts": [value]}])
        result = {
            text(str(key), 128): "[redacted]" if PROTECTED.search(str(key)) else
            sanitize(item, leaf_bytes=leaf_bytes, depth=depth + 1)
            for key, item in list(value.items())[:64]
        }
        if value.get("type") == "text" and not isinstance(result.get("content"), str):
            result["content"] = encode(result["content"])
        return result
    if isinstance(value, (tuple, list)):
        return [sanitize(item, leaf_bytes=leaf_bytes, depth=depth + 1) for item in value[:64]]
    if value is None or isinstance(value, (bool, int, float)):
        return value
    return "[unsupported]"


def _shrink(value: Any, budget: int) -> Any:
    if isinstance(value, str):
        return text(value, budget)
    if isinstance(value, list):
        return [_shrink(item, budget) for item in value[:MAX_PARTS]]
    if isinstance(value, dict):
        # Keep discriminator and role/name fields valid while bounding payloads.
        return {key: item if key in {"type", "role", "name"} else _shrink(item, budget)
                for key, item in value.items()}
    return value


def bounded(value: Any, *, schema: str | None = None, output: bool | None = None) -> tuple[str, bool]:
    safe = sanitize(value)
    if output is not None:
        safe = safe[:MAX_MESSAGES]
        for message in safe:
            message["parts"] = message["parts"][:MAX_PARTS]
    truncated = False
    for budget in (2048, 1024, 512, 256, 128, 64, 32, 16, 8):
        candidate = _shrink(safe, budget)
        serialized = encode(candidate)
        if len(serialized.encode("utf-8")) <= MAX_BYTES:
            if output is not None:
                validate_messages(candidate, output)
            if schema:
                VALIDATORS[PREFIX + schema + ".json"].validate(candidate)
            return serialized, truncated or candidate != safe
        truncated = True
    raise ValueError("content_attribute_exceeds_budget")


def messages(value: Any, *, output: bool = False, tool: str | None = None) -> tuple[str, bool]:
    safe = sanitize(value)
    if tool:
        part = ({"type": "tool_call_response", "response": safe} if output else
                {"type": "tool_call", "name": tool, "arguments": safe})
        role = "tool" if output else "assistant"
        carrier = [{"role": role, "parts": [part]}]
    elif isinstance(safe, list) and safe and all(isinstance(m, dict) and "role" in m and "parts" in m for m in safe):
        carrier = safe
    elif isinstance(safe, dict) and "type" in safe:
        carrier = [{"role": "assistant" if output else "user", "parts": [safe]}]
    else:
        carrier = [{"role": "assistant" if output else "user", "parts": [
            {"type": "text", "content": safe if isinstance(safe, str) else encode(safe)}]}]
    return bounded(carrier, output=output)

"""Bounded, redacted telemetry copies; business values are never modified.

Schemas are the complete supplied official snapshot, packaged with this module.
Known discriminators are additionally checked against their concrete schema so
the schema's GenericPart extension cannot accept a malformed known part.
"""
from __future__ import annotations

import json
import math
import re
from pathlib import Path

from jsonschema import Draft202012Validator

MAX_MESSAGES = 16
MAX_PARTS = 64
MAX_BYTES = 8192
SCHEMAS = json.loads(Path(__file__).with_name('genai_schemas.json').read_text())
VALIDATORS = {key: Draft202012Validator(value) for key, value in SCHEMAS.items()}
KNOWN = {
    definition['properties']['type']['const']: name
    for definition_schema in SCHEMAS.values()
    for name, definition in definition_schema.get('$defs', {}).items()
    if isinstance(definition.get('properties', {}).get('type'), dict)
    and 'const' in definition['properties']['type']
}
PROTECTED = re.compile(
    r'(?i)(?:hidden[_ -]?reasoning|private[_ -]?prompt|chain[_ -]?of[_ -]?thought|'
    r'reasoning|authorization|password|api[_ -]?key|access[_ -]?token|token|secret|'
    r'email|user[_ -]?id|tenant[_ -]?id|session[_ -]?id)'
)
LABELLED = re.compile(
    r'(?i)\b(?:hidden[_ -]?reasoning|private[_ -]?prompt|chain[_ -]?of[_ -]?thought|'
    r'reasoning|authorization|password|api[_ -]?key|access[_ -]?token|token|secret|'
    r'email|user[_ -]?id|tenant[_ -]?id|session[_ -]?id)\s*[:=]\s*'
    r'(?:"[^"\n]*"|\x27[^\x27\n]*\x27|[^;\n,]+)'
)
EMAIL = re.compile(r'\b[A-Za-z0-9.!#$%&\x27*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')
PRIVATE_TOKEN = re.compile(r'(?i)\b(?:private[-_]prompt|hidden[-_]reasoning)[-_][\w-]+')
OMIT = object()


class ContentRejected(ValueError):
    pass


def dumps(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'), allow_nan=False)


def utf8(text, limit):
    return text.encode('utf-8', errors='replace')[:limit].decode('utf-8', errors='ignore')


def validate_part(part, schema):
    name = KNOWN.get(part.get('type')) if isinstance(part, dict) else None
    if name:
        concrete = {'$defs': schema['$defs'], '$ref': '#/$defs/' + name}
        try:
            Draft202012Validator(concrete).validate(part)
        except Exception as error:
            raise ContentRejected('malformed_known_part') from error


def validate_messages(value, output=False):
    key = 'model/gen-ai/gen-ai-' + ('output' if output else 'input') + '-messages.json'
    schema = SCHEMAS[key]
    try:
        VALIDATORS[key].validate(value)
        for message in value:
            for part in message['parts']:
                validate_part(part, schema)
    except ContentRejected:
        raise
    except Exception as error:
        raise ContentRejected('invalid_messages') from error
    return value


def sanitize(value, depth=0):
    if depth > 12:
        return '[depth limit]'
    if isinstance(value, str):
        # Decode once at this level, then sanitize decoded scalar text too.
        try:
            parsed = json.loads(value)
        except (ValueError, RecursionError):
            parsed = OMIT
        if parsed is not OMIT and parsed != value:
            return sanitize(parsed, depth + 1)
        return utf8(EMAIL.sub('[redacted]', PRIVATE_TOKEN.sub('[redacted]', LABELLED.sub('[redacted]', value))), MAX_BYTES)
    if isinstance(value, dict):
        if value.get('type') in {'reasoning', 'compaction'}:
            return OMIT
        if value.get('type') in KNOWN:
            validate_part(value, SCHEMAS['model/gen-ai/gen-ai-input-messages.json'])
        result = {}
        for key, child in list(value.items())[:128]:
            if not isinstance(key, str) or PROTECTED.search(key):
                continue
            safe = sanitize(child, depth + 1)
            if safe is not OMIT:
                safe_key = utf8(EMAIL.sub('[redacted]', key), 128)
                result[safe_key] = safe
        return result
    if isinstance(value, (list, tuple)):
        return [safe for child in value[:MAX_PARTS] if (safe := sanitize(child, depth + 1)) is not OMIT]
    if value is None or type(value) in (bool, int):
        return value
    if type(value) is float and math.isfinite(value):
        return value
    return '[unsupported value]'


def _shrink(value, leaf_bytes):
    if isinstance(value, str):
        return utf8(value, leaf_bytes)
    if isinstance(value, list):
        return [_shrink(child, leaf_bytes) for child in value]
    if isinstance(value, dict):
        return {key: _shrink(child, leaf_bytes) for key, child in value.items()}
    return value


def bounded(value, budget=MAX_BYTES):
    """Reduce leaves before serializing; never slice serialized JSON."""
    for limit in (2048, 1024, 512, 256, 128, 64, 32, 16):
        candidate = _shrink(value, limit)
        if len(dumps(candidate).encode('utf-8')) <= budget:
            return candidate
    raise ContentRejected('aggregate_limit')


def safe_value(value, budget=6000, *, with_status=False):
    safe = sanitize(value)
    if safe is OMIT:
        raise ContentRejected('protected_content')
    reduced = bounded(safe, budget)
    return (reduced, reduced != safe) if with_status else reduced


def json_content(value):
    return dumps(safe_value(value, MAX_BYTES))


def messages(value, *, output=False, tool=None):
    safe = safe_value(value)
    if tool is not None:
        part = ({'type': 'tool_call_response', 'response': safe} if output else
                {'type': 'tool_call', 'name': tool, 'arguments': safe})
        payload = [{'role': 'tool' if output else 'assistant', 'parts': [part]}]
    elif isinstance(safe, list) and all(isinstance(row, dict) and 'role' in row for row in safe):
        payload = [{**row, 'parts': row['parts'][:MAX_PARTS]} for row in safe[:MAX_MESSAGES]]
    elif isinstance(safe, dict) and 'type' in safe:
        payload = [{'role': 'assistant' if output else 'user', 'parts': [safe]}]
    else:
        text = safe if isinstance(safe, str) else dumps(safe)
        payload = [{'role': 'assistant' if output else 'user', 'parts': [{'type': 'text', 'content': text}]}]
    validate_messages(payload, output)
    encoded = dumps(payload)
    if len(encoded.encode('utf-8')) > MAX_BYTES:
        raise ContentRejected('aggregate_limit')
    return encoded

