"""Live routing on the existing native trace export path; no provider ownership."""
import json
import logging
import os
import threading
from pathlib import Path
from uuid import UUID

from dotenv import set_key
from requests import Session
from opentelemetry.exporter.otlp.proto.http.trace_exporter import OTLPSpanExporter
from opentelemetry.sdk.resources import Resource
from opentelemetry.sdk.trace import ReadableSpan
from opentelemetry.sdk.trace.export import SpanExporter
from opentelemetry.util.re import parse_env_headers

from ao_resources import (
    StudioAPI, StudioAPIError, StudioProjects, StudioAgentStreams,
    ResolutionError, resolve_resources, native_trace_binding, STUDIO_HTTP_TIMEOUT,
)

HTTP_TIMEOUT_SECONDS = STUDIO_HTTP_TIMEOUT
RETRY_INITIAL_SECONDS = 0.5
RETRY_MAX_SECONDS = 2.0
RELOOKUP_ATTEMPTS = 3
RELOOKUP_DELAY_SECONDS = 0.25
_profile = None


def configure_profile(path):
    global _profile
    _profile = Path(path).resolve()


def valid_pair(project, stream):
    try:
        return all(isinstance(v, str) and str(UUID(v)) == v.lower() for v in (project, stream))
    except (ValueError, AttributeError):
        return False


class BindingSession(Session):
    """Public transport hook removes stale env routing before applying one pair."""
    def __init__(self, pair):
        super().__init__()
        self.pair = pair

    def prepare_request(self, request):
        prepared = super().prepare_request(request)
        for key in ('projectid', 'logstreamid'):
            prepared.headers.pop(key, None)
        if self.pair:
            prepared.headers.update(projectid=self.pair[0], logstreamid=self.pair[1])
        return prepared


class ResourceAPI(StudioAPI):
    def __init__(self, owner):
        super().__init__(owner.context['api'])
        self.owner = owner

    def request(self, method, path, body=None):
        if self.owner.stopped.is_set():
            raise StudioAPIError()
        if method == 'POST':
            key = json.dumps([path, body], sort_keys=True)
            # Fence before sending. A crash or uncertain response permits only
            # exact scoped relookup on later attempts, never another POST.
            if key in self.owner.state['creates']:
                raise StudioAPIError(uncertain_create=True)
            self.owner.state['creates'].append(key)
            self.owner.save_state()
        return super().request(method, path, body)


class NativeBindingExporter(SpanExporter):
    def __init__(self):
        self.lock = threading.Lock()
        self.stopped = threading.Event()
        self.worker = None
        self.profile = _profile
        self.state_path = self.profile.with_name(self.profile.name + '.ao-state.json') if self.profile else None
        self.context = {
            'api': os.getenv('AGENT_RESOURCE_API_URL', ''),
            'project': os.getenv('AGENT_PROJECT', ''),
            'stream': os.getenv('AGENT_STREAM', ''),
            'trace_endpoint': os.getenv('OTEL_EXPORTER_OTLP_TRACES_ENDPOINT', os.getenv('OTEL_EXPORTER_OTLP_ENDPOINT', '')),
        }
        raw = os.getenv('OTEL_EXPORTER_OTLP_TRACES_HEADERS', os.getenv('OTEL_EXPORTER_OTLP_HEADERS', ''))
        headers = parse_env_headers(raw, liberal=True)
        routing = {k.lower(): v for k, v in headers.items() if k.lower() in ('projectid', 'logstreamid')}
        self.harmless = {k: v for k, v in headers.items() if k.lower() not in ('projectid', 'logstreamid')}
        self.state = {'context': self.context, 'creates': [], 'pair': None}
        old = None
        if self.state_path and self.state_path.exists():
            try:
                old = json.loads(self.state_path.read_text())
                if old.get('context') == self.context:
                    self.state = old
            except (OSError, ValueError):
                old = {}  # A corrupt receipt cannot bless inherited headers.
        pair = self.state.get('pair')
        if not pair and old is None:
            pair = (routing.get('projectid'), routing.get('logstreamid'))
        self.pair = tuple(pair) if pair and len(pair) == 2 and valid_pair(*pair) else None
        self.delegate = self.make_delegate(self.pair)
        if all(self.context[k] for k in ('api', 'project', 'stream')):
            # One bounded synchronous attempt resolves connected one-shot runs
            # before the first business turn; retries never block business turns.
            if not self.resolve_once():
                self.worker = threading.Thread(target=self.recover, name='agent-resource-resolver', daemon=True)
                self.worker.start()

    def make_delegate(self, pair):
        return OTLPSpanExporter(headers=self.harmless, session=BindingSession(pair))

    def save_state(self):
        if self.state_path:
            temporary = self.state_path.with_suffix('.tmp')
            temporary.write_text(json.dumps(self.state, sort_keys=True))
            temporary.chmod(0o600)
            temporary.replace(self.state_path)

    def resolve_once(self):
        try:
            api = ResourceAPI(self)
            evidence = resolve_resources(
                StudioProjects(api), StudioAgentStreams(api),
                project_name=self.context['project'], agent_stream_name=self.context['stream'],
                reuse_only=os.getenv('AGENT_REUSE_ONLY', '').lower() in ('1', 'true'),
                relookup_attempts=RELOOKUP_ATTEMPTS, relookup_delay=RELOOKUP_DELAY_SECONDS,
                sleep=self.stopped.wait,
            )
            binding = native_trace_binding(evidence)
            pair = (binding['headers']['projectid'], binding['headers']['logstreamid'])
            with self.lock:
                if self.stopped.is_set():
                    return False
                replacement = self.make_delegate(pair)
                try:
                    self.state['pair'] = list(pair)
                    self.save_state()
                    if self.profile:
                        headers = {**self.harmless, **binding['headers']}
                        set_key(str(self.profile), 'OTEL_EXPORTER_OTLP_TRACES_HEADERS',
                                ','.join(f'{k}={v}' for k, v in headers.items()))
                except Exception:
                    replacement.shutdown()
                    raise
                previous = self.delegate
                self.delegate, self.pair = replacement, pair
                previous.shutdown()
            return True
        except (ResolutionError, ValueError, OSError, TypeError):
            logging.getLogger(__name__).warning('Agent resource resolution pending')
            return False

    def recover(self):
        delay = RETRY_INITIAL_SECONDS
        while not self.stopped.wait(delay):
            if self.resolve_once():
                return
            delay = min(RETRY_MAX_SECONDS, delay * 2)

    def export(self, spans):
        with self.lock:
            # One pair covers both immutable span views and the fixed transport.
            pair = self.pair
            views = spans
            if pair:
                attributes = {'splunk_ao.project.id': pair[0], 'splunk_ao.logstream.id': pair[1]}
                views = [ReadableSpan(
                    name=s.name, context=s.context, parent=s.parent,
                    resource=s.resource.merge(Resource(attributes)), attributes=s.attributes,
                    events=s.events, links=s.links, kind=s.kind, status=s.status,
                    start_time=s.start_time, end_time=s.end_time,
                    instrumentation_scope=s.instrumentation_scope,
                ) for s in spans]
            return self.delegate.export(views)

    def force_flush(self, timeout_millis=30000):
        with self.lock:
            return self.delegate.force_flush(timeout_millis)

    def shutdown(self):
        self.stopped.set()
        if self.worker:
            self.worker.join()
        with self.lock:
            self.delegate.shutdown()

